#define _CRT_SECURE_NO_WARNINGS
#include <stdio.h>
#include <stdlib.h>
#include <windows.h>

int main() {
    SetConsoleOutputCP(1251);
    SetConsoleCP(1251);

    char c; short s; int i; unsigned u; long l;
    float f; double d; long double ld;

    printf("Введіть char short int unsigned long float double long double:\n");
    scanf(" %c %hd %d %u %ld %f %lf %Lf", &c, &s, &i, &u, &l, &f, &d, &ld);

    printf("char        c  = '%c' (код %d)\n", c, c);
    printf("short       s  = %hd\n", s);
    printf("int         i  = %d\n", i);
    printf("unsigned    u  = %u\n", u);
    printf("long        l  = %ld\n", l);
    printf("float       f  = %f\t(%.10f)\n", f, f);
    printf("double      d  = %.10lf\n", d);
    printf("long double ld = %Lf\n", ld);
    printf("i у 16-й: %#x, у 8-й: %#o; d в e-формі: %e\n", i, i, d);

    system("pause");
    return 0;
}

